const p=(await browser.pages.list()).find(p=>p.ownership==='mine'&&p.url==='about:blank');
return await browser.page(p.pageId).evaluate(async()=>{const s=document.createElement('script');s.src='https://unpkg.com/@scion-scxml/scxml@4.3.28/dist/scxml.min.js';s.integrity='sha384-i0S34kl/f3wXxvBG3sa1Ydj7YxKNRwC/Tabj1I8IzPAeVy9GLjZpOr/usYSau9hT';s.crossOrigin='anonymous';await new Promise((resolve,reject)=>{s.onload=resolve;s.onerror=()=>reject(Error('Pinned original SCXML bundle failed to load'));document.head.append(s)});return {documentStringToModelAvailable:typeof scion.scxml.documentStringToModel==='function',StatechartAvailable:typeof scion.core.Statechart==='function',userAgent:navigator.userAgent}});
